def refs():
    return [{**s, "subject": "science", "locator": "原子、分子、化合物、光譜線、光年、恆星、星系與宇宙尺度的資料判讀", "observedPattern": "公開學校自然科試題常把粒子分類、光年換算、星系層級與觀測訊號放在資料題或情境題中；本題只採能力方向與資料型態。", "reuseDecision": "pattern-only", "status": "recorded", "locatorLevel": "paper"} for s in SOURCES]


def make(n, prompt, options, explanation, strategy, steps, difficulty):
    return {"id": f"question-science-content-cross-atoms-to-universe-{n}", "subject": "science", "type": "single-choice", "prompt": prompt, "options": [{"id": k, "text": v} for k, v in options.items()], "knowledgeIds": [KG], "difficulty": difficulty, "answer": {"value": "A", "explanation": explanation + "選 A。"}, "provenance": {"origin": "original", "license": "All rights reserved", "sourceUrl": SOURCES[0]["url"], "sourceLocator": "三筆公立學校公開自然科資料僅供粒子分類、天體層級、光年與觀測證據的能力方向研究；本題未複製原題、選項、圖表或答案。", "authoringNote": "依官方課綱、KG 與三筆公立學校公開自然科資料的能力方向獨立改寫；題幹、選項、答案、解析與五步解法均為原創，待第二輪 AI／Terra 內容複核。"}, "reviewStatus": "draft", "updatedAt": "2026-09-10", "lessonId": LESSON, "examPatternRefs": refs(), "solutionStrategy": strategy, "solutionSteps": steps}


Q = [
    make(1, "粒子卡顯示每個粒子都由兩個氫原子和一個氧原子固定連結。最合理的判讀是？", {"A": "這是由兩種元素按固定比例組成的化合物粒子，可寫成 H₂O", "B": "這只是氫元素和氧元素的任意混合", "C": "氧原子本身就是一個水分子", "D": "因為含有兩種元素，所以一定是兩個分子"}, "卡片同時顯示兩種元素與固定的原子數比，符合化合物分子的模型；數字下標表示單一粒子中的原子數。", "先數元素種類，再看是否固定連結與固定比例，最後才判斷化合物。", ["辨認卡片中的氫與氧兩種元素。", "確認每個粒子都重複同樣的 2:1 組成。", "確認它們是固定連結而非任意混合。", "把組成翻譯成 H₂O 的化學式。", "所以選 A。"], "easy"),
    make(2, "元素、原子、分子與化合物四個詞的關係，哪一項最精確？", {"A": "元素是原子種類；原子是粒子單位；分子可由原子組成；含不同元素固定結合的分子可屬化合物", "B": "元素就是一顆原子，兩者永遠完全同義", "C": "分子一定只含一種元素，不能形成化合物", "D": "化合物只要看名稱，不必檢查組成"}, "元素指具有相同質子數的原子種類，不等於單一顆粒子；分子與化合物則要依粒子組成和元素種類判斷。", "把每個名詞的層次分開，再用粒子組成連結它們。", ["先區分『種類』和『單一粒子』。", "確認分子是由原子組成的粒子單位。", "檢查分子含一種或多種元素。", "不同元素固定結合時才符合化合物的條件。", "所以選 A。"], "medium"),
    make(3, "未知恆星的光譜暗線與實驗室鈉光譜的特徵線位置相同，最合適的結論是？", {"A": "恆星大氣可能含鈉，還要考慮溫度、壓力與儀器校正等條件", "B": "恆星一定和實驗室鈉樣品一樣重", "C": "只看暗線就能算出恆星距離地球幾公里", "D": "暗線表示恆星沒有任何其他元素"}, "相同位置的光譜線可支持成分推論，但不能由一組線直接推出質量、距離或排除其他成分。", "把觀測訊號能支持的結論與不能單獨支持的結論分開。", ["找出未知光譜與參考光譜相符的特徵。", "把特徵線與原子或元素的光互動連起來。", "用『可能含有』而非『唯一含有』表達結論。", "檢查距離與其他物性是否需要額外資料。", "所以選 A。"], "medium"),
    make(4, "某星距離地球 26 光年，『光年』在此處代表什麼？", {"A": "光在真空中一年所走的距離，是距離單位", "B": "光從該星抵達地球所需的 26 秒", "C": "該星的年齡為 26 歲", "D": "光的速度是 26 倍"}, "光年以光一年行進的路程定義，是距離單位；26 光年也表示我們現在看到的是約 26 年前出發的光。", "先辨認單位的物理量，再處理由傳播時間形成的觀測延遲。", ["看到『光年』先問它量的是時間還是距離。", "用光一年走過的路程判定它是距離單位。", "把 26 光年理解成光行進的路程。", "再推論抵達地球的光約帶著 26 年前的訊息。", "所以選 A。"], "easy"),
    make(5, "整理原子、太陽系、銀河系與宇宙的尺度時，哪種做法最可靠？", {"A": "先確認每一層的定義、包含關係與單位，不把示意圖畫得大當成真實比例", "B": "只依圖形面積判定各層的真實大小", "C": "把銀河系視為太陽系的另一個名稱", "D": "把宇宙當成一顆比星系更大的恆星"}, "尺度圖是整理關係的工具，必須搭配定義和單位判讀；畫面大小不能取代實際尺度證據。", "先讀圖例與單位，再用包含關係檢查層級，而非直接量畫面。", ["列出題目要比較的四種層級。", "確認太陽系位於銀河系內，銀河系又是宇宙中的星系。", "檢查圖表提供的單位與比例說明。", "排除把示意圖的視覺大小當實際測量值。", "所以選 A。"], "medium"),
    make(6, "一顆紅色恆星比一顆藍色恆星看起來暗，仍不能只由這兩項資訊判定什麼？", {"A": "不能只由顏色與視亮度決定它們的距離，還需要距離或光度等額外資料", "B": "不能知道它們是否都是恆星", "C": "不能知道任何星光曾經傳到地球", "D": "不能把顏色當作任何觀測資料"}, "顏色可提供溫度的線索，視亮度同時受距離與本身光度影響，因此不能只靠兩者唯一決定距離。", "辨認每項觀測量能支持的變項，並找出會造成同一結果的替代原因。", ["把顏色和視亮度分開列為觀測量。", "知道顏色可作表面溫度的線索。", "知道視亮度同時受本身光度和距離影響。", "提出需要絕對光度或其他距離指標的補充資料。", "所以選 A。"], "hard"),
    make(7, "若兩個星系的相同元素光譜線中，甲的波長較長，依紅移的基本判讀可先推論什麼？", {"A": "甲的光譜較偏紅，可能表示甲相對觀測者的遠離運動較明顯，但仍要依完整資料判斷", "B": "甲一定比乙小", "C": "甲的星星一定都比乙冷", "D": "甲一定位於銀河系內而乙在銀河系外"}, "同一光譜線波長變長是紅移線索，可支持遠離運動的初步推論；不能直接推出大小、溫度或所屬星系。", "先比較同一條參考線的位移，再限制結論只到資料能支持的程度。", ["找出兩個星系共同的參考光譜線。", "比較甲的波長是否向長波方向偏移。", "把長波偏移連到紅移與遠離的初步模型。", "排除由紅移直接推定大小、溫度或位置的說法。", "所以選 A。"], "hard"),
    make(8, "下列哪一個例子最能說明科學家如何研究無法直接取樣的恆星？", {"A": "分析恆星光譜的特徵線，和實驗室參考資料比對以推論成分", "B": "把望遠鏡看到的星星取下來放入試管", "C": "只用星星在圖片中的像素大小判定全部性質", "D": "用星座名稱直接當作化學分析結果"}, "恆星無法直接取樣，但光譜是可觀察訊號；與已知元素的參考光譜比較可建立有證據的成分模型。", "找出實際觀測量與參考資料，再說明推論如何受到模型限制。", ["確認恆星不能像實驗室樣品一樣直接取樣。", "找出可被儀器記錄的星光光譜。", "與已知元素參考線逐一比對。", "把結果寫成有條件的成分推論，而非直接看見原子。", "所以選 A。"], "medium"),
    make(9, "某尺度圖把原子畫成和行星一樣大的圓，這張圖仍可能有用的原因是？", {"A": "它可用來表示層級或概念關係，但圖上的圓大小不代表真實比例", "B": "它證明原子和行星的實際直徑相等", "C": "它表示所有尺度都應使用相同單位", "D": "它能單獨測出宇宙的年齡"}, "示意圖可以放大微觀對象以便閱讀，重點是表示關係；若沒有比例尺，不能把圖形大小當成真實尺寸。", "先判斷圖的用途，再檢查有無比例尺和單位。", ["辨認這是示意圖而非按比例照片。", "找出圖中要表達的包含或順序關係。", "檢查是否提供實際比例尺與單位。", "把可支持的關係和不能支持的尺寸結論分開。", "所以選 A。"], "easy"),
    make(10, "從粒子卡、光譜與尺度圖得到科學結論時，哪個作答框架最完整？", {"A": "指出直接觀察，說明由此提出的模型推論，再標示仍需補充的證據與限制", "B": "直接把圖上的符號當成實物，不必說明證據", "C": "只寫最後答案，不必區分觀察和推論", "D": "只要結論聽起來合理，就可忽略單位與參考資料"}, "跨尺度研究都要把訊號、模型和限制分開；這能避免把示意表示或單一線索誤當成完整事實。", "使用『證據—推論—限制』三欄回查每個結論。", ["列出題目真正提供的符號、線條或數值。", "說明這些資料支持哪個模型或分類。", "檢查模型是否需要單位、參考資料或其他假設。", "寫出目前無法由資料確定的部分。", "所以選 A。"], "medium"),
]

for index, target in {2: "B", 4: "C", 6: "D", 8: "B", 10: "C"}.items():
    q = Q[index - 1]
    option_map = {o["id"]: o["text"] for o in q["options"]}
    option_map["A"], option_map[target] = option_map[target], option_map["A"]
    q["options"] = [{"id": k, "text": option_map[k]} for k in ("A", "B", "C", "D")]
    q["answer"]["value"] = target
    q["answer"]["explanation"] = q["answer"]["explanation"].replace("選 A。", f"選 {target}。")
    q["solutionSteps"] = [s.replace("所以選 A。", f"所以選 {target}。") for s in q["solutionSteps"]]

for q in Q:
    (OUT / f"{q['id']}.json").write_text(json.dumps(q, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
print(f"rewrote {len(Q)} questions")
